import unittest
from candidate import common
from unittest.mock import unittest

class TestCommonElements(unittest.TestCase):
    def test_common_empty_lists(self):
        self.assertListEqual(common([] [], []), [])

    def test_common_single_element_lists(self):
        self.assertListEqual(common([1], [1]), [1])
        self.assertListEqual(common([2], [2]), [2])

    def test_common_equal_lists(self):
        self.assertListEqual(common([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 9, 653, 121]), [1, 5, 653])

    def test_common_lists_with_duplicates(self):
        self.assertListEqual(common([1, 4, 3, 34, 653, 2, 5, 2, 2], [5, 7, 1, 5, 9, 653, 121, 2]), [1, 2, 5, 653])

    def test_common_lists_with_sorted_different_elements(self):
        self.assertListEqual(common([34, 653, 2, 5, 1], [121, 5, 9, 653, 1, 7, 3, 2]), [1, 2, 5, 653])

    def test_common_lists_with_unsorted_different_elements(self):
        self.assertListEqual(common([5, 1, 2, 653, 34], [121, 7, 3, 9, 653, 2, 5]), [1, 2, 5, 653])

    def test_common_lists_with_no_common_elements(self):
        self.assertListEqual(common([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 9, 121]), [])

    def test_common_lists_with_negative_elements(self):
        self.assertListEqual(common([-1, 4, 3, 34, 653, 2, 5], [-1, 7, -2, 5, 9, -121]), [4, 5])

    def test_common_lists_with_non_list_inputs(self):
        self.assertRaises(TypeError, common, "list1", [2, 3])
        self.assertRaises(TypeError, common, [2, 3], "list2")

    def test_common_lists_with_one_none_input(self):
        self.assertRaises(TypeError, common, [None, 2, 3], [2, 3])
        self.assertRaises(TypeError, common, [2, 3], [None])

if __name__ == '__main__':
    unittest.main()
